"""Algorithm A — Berggren tree enumeration with hypotenuse residue audit."""

from __future__ import annotations

import math
from collections import deque
from typing import Dict, Iterator, List, Tuple

Triple = Tuple[int, int, int]


def berggren_children(t: Triple) -> Tuple[Triple, Triple, Triple]:
    """The three unimodular Berggren transformations applied to (a, b, c)."""
    a, b, c = t
    return (
        (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c),
        (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c),
        (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c),
    )


def berggren_bfs(max_nodes: int) -> Iterator[Tuple[int, Triple]]:
    """Breadth-first enumeration of the tree rooted at (3, 4, 5)."""
    queue: "deque[Tuple[int, Triple]]" = deque([(0, (3, 4, 5))])
    emitted = 0
    while queue and emitted < max_nodes:
        depth, t = queue.popleft()
        yield depth, t
        emitted += 1
        for child in berggren_children(t):
            queue.append((depth + 1, child))


def prime_divisors(n: int) -> List[int]:
    """Distinct prime divisors by trial division."""
    out: List[int] = []
    m, d = n, 2
    while d * d <= m:
        if m % d == 0:
            out.append(d)
            while m % d == 0:
                m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        out.append(m)
    return out


def nodes_up_to(depth: int) -> int:
    """Number of nodes of depth <= `depth` in a ternary tree: (3^(d+1) - 1)/2."""
    return (3 ** (depth + 1) - 1) // 2


def hypotenuse_audit(max_nodes: int) -> Dict[str, object]:
    """Enumerate the tree and certify the arithmetic constraints.

    Returns a report containing:
      * whether every prime divisor of every hypotenuse is  = 1 (mod 4);
      * the set of hypotenuse primes encountered;
      * the largest hypotenuse seen and the starvation ceiling 5 n^2;
      * the deepest level reached.
    """
    all_one_mod_four = True
    hyp_primes: set = set()
    max_hyp = 0
    max_depth = 0
    count = 0
    for depth, (a, b, c) in berggren_bfs(max_nodes):
        count += 1
        max_depth = max(max_depth, depth)
        max_hyp = max(max_hyp, c)
        assert a * a + b * b == c * c, "Pythagorean invariant violated"
        for r in prime_divisors(c):
            hyp_primes.add(r)
            if r % 4 != 1:
                all_one_mod_four = False
    ceiling = 5 * count * count
    return {
        "nodes": count,
        "max_depth": max_depth,
        "all_hypotenuse_primes_one_mod_four": all_one_mod_four,
        "distinct_hypotenuse_primes": sorted(hyp_primes),
        "max_hypotenuse": max_hyp,
        "starvation_ceiling_5n2": ceiling,
        "ceiling_respected": max_hyp <= ceiling,
        "geometric_ceiling_5_times_7_pow_depth": 5 * 7 ** max_depth,
    }


def blind_modulus_check(N: int, max_nodes: int = 2000) -> Dict[str, object]:
    """Count tree hypotenuses sharing a factor with N (0 iff N is blind)."""
    hits = [c for _, (_, _, c) in berggren_bfs(max_nodes) if math.gcd(c, N) > 1]
    return {
        "N": N,
        "prime_factors": prime_divisors(N),
        "all_factors_three_mod_four": all(r % 4 == 3 for r in prime_divisors(N)),
        "hypotenuse_hits": len(hits),
        "nodes_scanned": max_nodes,
    }


if __name__ == "__main__":
    report = hypotenuse_audit(300)
    for k, v in report.items():
        if k == "distinct_hypotenuse_primes":
            v = str(v[:15]) + " ..."
        print(f"{k:42s} {v}")
    print()
    for N in (77, 437, 11021, 3233):
        print(blind_modulus_check(N))

"""Algorithm D — norm-form blindness screening test for structured searches."""

from __future__ import annotations

import math
from typing import Dict, List, Sequence


def legendre(a: int, r: int) -> int:
    """Legendre symbol (a | r) for an odd prime r, by Euler's criterion."""
    a %= r
    if a == 0:
        return 0
    t = pow(a, (r - 1) // 2, r)
    return 1 if t == 1 else -1


def is_inert(r: int, D: int) -> bool:
    """r is inert for the form x^2 + D y^2 iff -D is a non-square modulo r.

    By the norm-form constraint, if c = a^2 + D b^2 with (a, b) primitive then
    -D is a square modulo every prime divisor of c.  So an inert prime can
    never divide a primitively represented value: the search is blind to it.
    """
    if r == 2:
        return False
    return legendre(-D, r) == -1


def prime_divisors(n: int) -> List[int]:
    out: List[int] = []
    m, d = n, 2
    while d * d <= m:
        if m % d == 0:
            out.append(d)
            while m % d == 0:
                m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        out.append(m)
    return out


def blind_primes(D: int, limit: int) -> List[int]:
    """All primes below `limit` that are inert for x^2 + D y^2."""
    sieve = bytearray([1]) * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i:: i] = bytearray(len(sieve[i * i:: i]))
    return [r for r in range(3, limit + 1) if sieve[r] and is_inert(r, D)]


def screen_modulus(N: int, D: int) -> Dict[str, object]:
    """The one-line screening test for a structured-search factoring proposal.

    If every prime factor of N is inert for the search's norm form, then the
    search has gcd(value, N) = 1 for *every* value it will ever produce: zero
    winning tickets, uniformly, at any depth and for any compute budget.
    """
    factors = prime_divisors(N)
    inert = [r for r in factors if is_inert(r, D)]
    return {
        "N": N,
        "form": f"x^2 + {D} y^2",
        "prime_factors": factors,
        "inert_factors": inert,
        "blind": len(inert) == len(factors) and len(factors) > 0,
    }


def certify_constraint(D: int, bound: int = 40) -> int:
    """Exhaustively verify the norm-form constraint on primitive (a, b).

    Returns the number of violations found (should be 0).
    """
    violations = 0
    for a in range(1, bound):
        for b in range(1, bound):
            if math.gcd(a, b) != 1:
                continue
            c = a * a + D * b * b
            for r in prime_divisors(c):
                if is_inert(r, D):
                    violations += 1
    return violations


if __name__ == "__main__":
    for D in (1, 2, 3, 7):
        print(f"D = {D:2d}  blind primes < 80: {blind_primes(D, 80)}")
        print(f"        constraint violations on primitive (a,b) < 40: "
              f"{certify_constraint(D)}")
    print()
    for N, D in ((7 * 11, 1), (7 * 11, 2), (5 * 13, 2), (5 * 13, 1)):
        print(screen_modulus(N, D))
